def split_admin_accounts(apps, schema_editor):
    """Website admins used to double as Django Admin users. Now they are website-only;
    Django Admin needs its own SITEADMIN account (manage.py createsuperuser)."""
    User = apps.get_model("users", "User")
    User.objects.filter(role="ADMIN").update(is_staff=False, is_superuser=False)
    User.objects.filter(role__in=["TEACHER", "STUDENT"]).update(is_staff=False, is_superuser=False)


def rejoin_admin_accounts(apps, schema_editor):
    User = apps.get_model("users", "User")
    User.objects.filter(role="ADMIN").update(is_staff=True, is_superuser=True)
    User.objects.filter(role="SITEADMIN").update(role="ADMIN")


